import sys

def main():
    input_lines = sys.stdin.read().strip().splitlines()
    n, t = map(int, input_lines[0].split())
    chars = list(input_lines[1].strip())

    for _ in range(t):
        j = 0
        while j < n - 1:
            if chars[j] == 'B' and chars[j + 1] == 'G':
                chars[j], chars[j + 1] = 'G', 'B'
                j += 1
            j += 1

    print(''.join(chars))

if __name__ == "__main__":
    main()

